1	import { useState, useEffect, useRef, useCallback } from "react";
2	import { toast } from "sonner";
3	import { Globe, Copy, ExternalLink, Loader2, Save, Eye } from "lucide-react";
4	import SidebarLayout from "@/components/SidebarLayout";
5	import { FadeIn } from "@/components/ui/fade-in";
6	import { StaggerList } from "@/components/ui/stagger-list";
7	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
8	import { Button } from "@/components/ui/button";
9	import { Input } from "@/components/ui/input";
10	import { Textarea } from "@/components/ui/textarea";
11	import { Label } from "@/components/ui/label";
12	import { Switch } from "@/components/ui/switch";
13	import { Badge } from "@/components/ui/badge";
14	import { Skeleton } from "@/components/ui/skeleton";
15	import {
16	  Table,
17	  TableBody,
18	  TableCell,
19	  TableHead,
20	  TableHeader,
21	  TableRow,
22	} from "@/components/ui/table";
23	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
24	import { supabase } from "@/integrations/supabase/client";
25	import { useAuth } from "@/hooks/useAuth";
26	import { useTeam } from "@/hooks/useTeam";
27	
28	// ---------------------------------------------------------------------------
29	// Types
30	// ---------------------------------------------------------------------------
31	
32	interface CareerPageConfig {
33	  id: string;
34	  team_id: string;
35	  company_name: string | null;
36	  slug: string | null;
37	  logo_url: string | null;
38	  brand_color: string | null;
39	  tagline: string | null;
40	  about: string | null;
41	  is_active: boolean;
42	}
43	
44	interface CareerJob {
45	  id: string;
46	  title: string | null;
47	  location: string | null;
48	  department: string | null;
49	  employment_type: string | null;
50	  is_published: boolean | null;
51	  status: string | null;
52	}
53	
54	type SlugStatus = "idle" | "checking" | "available" | "taken";
55	
56	// ---------------------------------------------------------------------------
57	// Helpers
58	// ---------------------------------------------------------------------------
59	
60	function slugify(name: string): string {
61	  return name
62	    .toLowerCase()
63	    .replace(/[^a-z0-9]+/g, "-")
64	    .replace(/^-|-$/g, "")
65	    .slice(0, 60);
66	}
67	
68	function isValidHex(value: string): boolean {
69	  return /^#([0-9A-Fa-f]{3}|[0-9A-Fa-f]{6})$/.test(value);
70	}
71	
72	// ---------------------------------------------------------------------------
73	// Skeleton components
74	// ---------------------------------------------------------------------------
75	
76	function ConfigSkeleton() {
77	  return (
78	    <div className="space-y-5">
79	      {[1, 2, 3, 4, 5, 6].map((i) => (
80	        <div key={i} className="space-y-1.5">
81	          <Skeleton className="h-4 w-24" />
82	          <Skeleton className="h-9 w-full" />
83	        </div>
84	      ))}
85	      <Skeleton className="h-9 w-28 mt-2" />
86	    </div>
87	  );
88	}
89	
90	function JobsSkeleton() {
91	  return (
92	    <div className="space-y-0">
93	      {[1, 2, 3].map((i) => (
94	        <div key={i} className="flex items-center gap-4 px-4 py-3 border-b border-border last:border-0">
95	          <Skeleton className="h-4 flex-1" />
96	          <Skeleton className="h-4 w-24" />
97	          <Skeleton className="h-4 w-20" />
98	          <Skeleton className="h-5 w-10 rounded-full" />
99	        </div>
100	      ))}
101	    </div>
102	  );
103	}
104	
105	// ---------------------------------------------------------------------------
106	// Slug status indicator
107	// ---------------------------------------------------------------------------
108	
109	function SlugStatusBadge({ status }: { status: SlugStatus }) {
110	  if (status === "idle") return null;
111	  if (status === "checking") {
112	    return (
113	      <span className="flex items-center gap-1 text-xs text-muted-foreground">
114	        <Loader2 className="h-3 w-3 animate-spin" />
115	        Checking…
116	      </span>
117	    );
118	  }
119	  if (status === "available") {
120	    return (
121	      <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400">
122	        Available
123	      </Badge>
124	    );
125	  }
126	  return (
127	    <Badge variant="outline" className="text-xs border-destructive/50 text-destructive">
128	      Already taken
129	    </Badge>
130	  );
131	}
132	
133	// ---------------------------------------------------------------------------
134	// Main page
135	// ---------------------------------------------------------------------------
136	
137	const CareerSettings = () => {
138	  const { user } = useAuth();
139	  const { team } = useTeam();
140	  const queryClient = useQueryClient();
141	
142	  const teamId = team?.id ?? null;
143	  const userId = user?.id ?? null;
144	
145	  // ----- Form state -----
146	  const [companyName, setCompanyName] = useState("");
147	  const [slug, setSlug] = useState("");
148	  const [logoUrl, setLogoUrl] = useState("");
149	  const [brandColor, setBrandColor] = useState("#6366f1");
150	  const [tagline, setTagline] = useState("");
151	  const [about, setAbout] = useState("");
152	  const [isActive, setIsActive] = useState(false);
153	  const [configId, setConfigId] = useState<string | null>(null);
154	  const [isSaving, setIsSaving] = useState(false);
155	  const [slugStatus, setSlugStatus] = useState<SlugStatus>("idle");
156	  const [slugManuallyEdited, setSlugManuallyEdited] = useState(false);
157	  const [togglingJobId, setTogglingJobId] = useState<string | null>(null);
158	
159	  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
160	
161	  // ----- Career page URL -----
162	  const careerPageUrl = slug ? `${window.location.origin}/careers/${slug}` : null;
163	
164	  // ----- Fetch config -----
165	  const { data: configData, isLoading: configLoading } = useQuery({
166	    queryKey: ["career-page-config", teamId],
167	    queryFn: async () => {
168	      if (!teamId) return null;
169	      const { data, error } = await (supabase as any)
170	        .from("career_page_config")
171	        .select("*")
172	        .eq("team_id", teamId)
173	        .maybeSingle();
174	      if (error) throw new Error(error.message);
175	      return data as CareerPageConfig | null;
176	    },
177	    enabled: !!teamId,
178	    staleTime: 60_000,
179	  });
180	
181	  // Populate form when config loads
182	  useEffect(() => {
183	    if (configData) {
184	      setConfigId(configData.id);
185	      setCompanyName(configData.company_name ?? "");
186	      setSlug(configData.slug ?? "");
187	      setLogoUrl(configData.logo_url ?? "");
188	      setBrandColor(configData.brand_color ?? "#6366f1");
189	      setTagline(configData.tagline ?? "");
190	      setAbout(configData.about ?? "");
191	      setIsActive(configData.is_active ?? false);
192	      setSlugManuallyEdited(true); // Don't auto-overwrite on subsequent renders
193	    } else if (!configLoading && team?.name) {
194	      // Pre-fill from team name on first load
195	      setCompanyName(team.name);
196	      const auto = slugify(team.name);
197	      setSlug(auto);
198	    }
199	  }, [configData, configLoading, team?.name]);
200	
201	  // ----- Fetch jobs -----
202	  const { data: jobs = [], isLoading: jobsLoading } = useQuery({
203	    queryKey: ["career-jobs", userId],
204	    queryFn: async () => {
205	      if (!userId) return [];
206	      const { data, error } = await (supabase as any)
207	        .from("jobs")
208	        .select("id, title, location, department, employment_type, is_published, status")
209	        .eq("user_id", userId)
210	        .order("created_at", { ascending: false });
211	      if (error) throw new Error(error.message);
212	      return (data ?? []) as CareerJob[];
213	    },
214	    enabled: !!userId,
215	    staleTime: 30_000,
216	  });
217	
218	  // ----- Slug auto-gen from company name -----
219	  const handleCompanyNameChange = (value: string) => {
220	    setCompanyName(value);
221	    if (!slugManuallyEdited) {
222	      const auto = slugify(value);
223	      setSlug(auto);
224	      triggerSlugCheck(auto);
225	    }
226	  };
227	
228	  // ----- Slug check debounce -----
229	  const triggerSlugCheck = useCallback(
230	    (value: string) => {
231	      if (debounceRef.current) clearTimeout(debounceRef.current);
232	      if (!value || !teamId) {
233	        setSlugStatus("idle");
234	        return;
235	      }
236	      setSlugStatus("checking");
237	      debounceRef.current = setTimeout(async () => {
238	        try {
239	          const { data, error } = await (supabase as any).rpc("is_career_slug_available", {
240	            p_slug: value,
241	            p_team_id: teamId,
242	          });
243	          if (error) throw error;
244	          setSlugStatus(data === true ? "available" : "taken");
245	        } catch {
246	          setSlugStatus("idle");
247	        }
248	      }, 600);
249	    },
250	    [teamId]
251	  );
252	
253	  const handleSlugChange = (value: string) => {
254	    const clean = value.toLowerCase().replace(/[^a-z0-9-]/g, "").slice(0, 60);
255	    setSlug(clean);
256	    setSlugManuallyEdited(true);
257	    triggerSlugCheck(clean);
258	  };
259	
260	  // Cleanup debounce on unmount
261	  useEffect(() => {
262	    return () => {
263	      if (debounceRef.current) clearTimeout(debounceRef.current);
264	    };
265	  }, []);
266	
267	  // ----- Save config -----
268	  const handleSave = async () => {
269	    if (!teamId) {
270	      toast.error("No team found. Create a team first.");
271	      return;
272	    }
273	    if (!companyName.trim()) {
274	      toast.error("Company name is required.");
275	      return;
276	    }
277	    if (!slug.trim()) {
278	      toast.error("URL slug is required.");
279	      return;
280	    }
281	    if (slugStatus === "taken") {
282	      toast.error("That slug is already taken. Choose a different one.");
283	      return;
284	    }
285	
286	    setIsSaving(true);
287	    try {
288	      const payload = {
289	        team_id: teamId,
290	        company_name: companyName.trim(),
291	        slug: slug.trim(),
292	        logo_url: logoUrl.trim() || null,
293	        brand_color: isValidHex(brandColor) ? brandColor : "#6366f1",
294	        tagline: tagline.trim() || null,
295	        about: about.trim() || null,
296	        is_active: isActive,
297	      };
298	
299	      let error: unknown;
300	
301	      if (configId) {
302	        const res = await (supabase as any)
303	          .from("career_page_config")
304	          .update(payload)
305	          .eq("id", configId);
306	        error = res.error;
307	      } else {
308	        const res = await (supabase as any)
309	          .from("career_page_config")
310	          .insert(payload)
311	          .select("id")
312	          .single();
313	        error = res.error;
314	        if (!res.error && res.data?.id) {
315	          setConfigId(res.data.id);
316	        }
317	      }
318	
319	      if (error) throw error;
320	
321	      toast.success("Career page saved");
322	      queryClient.invalidateQueries({ queryKey: ["career-page-config", teamId] });
323	    } catch (err: unknown) {
324	      const msg = err instanceof Error ? err.message : "Failed to save career page";
325	      toast.error(msg);
326	    } finally {
327	      setIsSaving(false);
328	    }
329	  };
330	
331	  // ----- Toggle job published -----
332	  const toggleJobPublished = useMutation({
333	    mutationFn: async ({ jobId, current }: { jobId: string; current: boolean }) => {
334	      const { error } = await (supabase as any)
335	        .from("jobs")
336	        .update({ is_published: !current })
337	        .eq("id", jobId);
338	      if (error) throw new Error(error.message);
339	      return { jobId, newValue: !current };
340	    },
341	    onMutate: ({ jobId }) => {
342	      setTogglingJobId(jobId);
343	    },
344	    onSuccess: ({ jobId, newValue }) => {
345	      queryClient.setQueryData(["career-jobs", userId], (old: CareerJob[] | undefined) =>
346	        (old ?? []).map((j) => (j.id === jobId ? { ...j, is_published: newValue } : j))
347	      );
348	      toast.success(newValue ? "Job published to career page" : "Job unpublished");
349	    },
350	    onError: (err: unknown) => {
351	      const msg = err instanceof Error ? err.message : "Failed to update job";
352	      toast.error(msg);
353	    },
354	    onSettled: () => {
355	      setTogglingJobId(null);
356	    },
357	  });
358	
359	  // ----- Clipboard copy -----
360	  function copyUrl() {
361	    if (!careerPageUrl) return;
362	    navigator.clipboard.writeText(careerPageUrl).then(
363	      () => toast.success("Link copied"),
364	      () => toast.error("Could not copy link")
365	    );
366	  }
367	
368	  // ---------------------------------------------------------------------------
369	  // Render
370	  // ---------------------------------------------------------------------------
371	
372	  return (
373	    <SidebarLayout>
374	      <main className="w-full max-w-[760px] mx-auto px-4 sm:px-6 lg:px-8 py-8">
375	        <FadeIn>
376	          <div className="flex items-start justify-between mb-1">
377	            <h1 className="text-xl font-semibold text-foreground tracking-tight">Career Page</h1>
378	            {isActive && careerPageUrl && (
379	              <div className="flex items-center gap-1.5">
380	                <Badge variant="outline" className="text-xs border-green-500/50 text-green-600 dark:text-green-400 gap-1">
381	                  <Eye className="h-3 w-3" />
382	                  Live
383	                </Badge>
384	                <Button
385	                  variant="ghost"
386	                  size="icon"
387	                  className="h-7 w-7"
388	                  onClick={copyUrl}
389	                  aria-label="Copy career page URL"
390	                >
391	                  <Copy className="h-3.5 w-3.5" />
392	                </Button>
393	                <Button
394	                  variant="ghost"
395	                  size="icon"
396	                  className="h-7 w-7"
397	                  onClick={() => window.open(careerPageUrl, "_blank")}
398	                  aria-label="Open career page"
399	                >
400	                  <ExternalLink className="h-3.5 w-3.5" />
401	                </Button>
402	              </div>
403	            )}
404	          </div>
405	          <p className="text-sm text-muted-foreground mb-6">
406	            Customize your public career page and manage which jobs are visible to candidates.
407	          </p>
408	        </FadeIn>
409	
410	        <StaggerList className="space-y-6" stagger={0.08}>
411	          {/* ---------------------------------------------------------------- */}
412	          {/* Card 1: Configuration                                             */}
413	          {/* ---------------------------------------------------------------- */}
414	          <Card>
415	            <CardHeader className="pb-3">
416	              <CardTitle className="text-sm font-semibold flex items-center gap-2">
417	                <Globe className="h-4 w-4 text-primary" />
418	                Career Page Configuration
419	              </CardTitle>
420	              <CardDescription className="text-xs">
421	                Set up your branded career page. Share the link with candidates.
422	              </CardDescription>
423	            </CardHeader>
424	            <CardContent>
425	              {configLoading ? (
426	                <ConfigSkeleton />
427	              ) : (
428	                <div className="space-y-5">
429	                  {/* Company name */}
430	                  <div className="space-y-1.5">
431	                    <Label htmlFor="company-name" className="text-xs font-medium">
432	                      Company name
433	                    </Label>
434	                    <Input
435	                      id="company-name"
436	                      placeholder="Acme Corp"
437	                      value={companyName}
438	                      onChange={(e) => handleCompanyNameChange(e.target.value)}
439	                      disabled={isSaving}
440	                    />
441	                  </div>
442	
443	                  {/* Slug */}
444	                  <div className="space-y-1.5">
445	                    <div className="flex items-center justify-between">
446	                      <Label htmlFor="slug" className="text-xs font-medium">
447	                        URL slug
448	                      </Label>
449	                      <SlugStatusBadge status={slugStatus} />
450	                    </div>
451	                    <div className="flex items-center rounded-md border border-input bg-background ring-offset-background focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 overflow-hidden">
452	                      <span className="flex items-center pl-3 pr-1 text-xs text-muted-foreground whitespace-nowrap shrink-0 select-none">
453	                        /careers/
454	                      </span>
455	                      <input
456	                        id="slug"
457	                        className="flex-1 py-2 pr-3 text-sm bg-transparent outline-none placeholder:text-muted-foreground"
458	                        placeholder="acme-corp"
459	                        value={slug}
460	                        onChange={(e) => handleSlugChange(e.target.value)}
461	                        disabled={isSaving}
462	                        spellCheck={false}
463	                        aria-describedby="slug-hint"
464	                      />
465	                    </div>
466	                    <p id="slug-hint" className="text-xs text-muted-foreground">
467	                      Lowercase letters, numbers, and hyphens only.
468	                    </p>
469	                  </div>
470	
471	                  {/* Logo URL */}
472	                  <div className="space-y-1.5">
473	                    <Label htmlFor="logo-url" className="text-xs font-medium">
474	                      Logo URL
475	                    </Label>
476	                    <Input
477	                      id="logo-url"
478	                      placeholder="https://example.com/logo.png"
479	                      value={logoUrl}
480	                      onChange={(e) => setLogoUrl(e.target.value)}
481	                      disabled={isSaving}
482	                      type="url"
483	                    />
484	                  </div>
485	
486	                  {/* Brand color */}
487	                  <div className="space-y-1.5">
488	                    <Label className="text-xs font-medium">Brand color</Label>
489	                    <div className="flex items-center gap-2">
490	                      <div className="relative h-9 w-14 shrink-0">
491	                        <input
492	                          type="color"
493	                          className="absolute inset-0 h-full w-full cursor-pointer rounded-md border border-input opacity-0"
494	                          value={isValidHex(brandColor) ? brandColor : "#6366f1"}
495	                          onChange={(e) => setBrandColor(e.target.value)}
496	                          disabled={isSaving}
497	                          aria-label="Pick brand color"
498	                        />
499	                        <div
500	                          className="h-full w-full rounded-md border border-input"
501	                          style={{ backgroundColor: isValidHex(brandColor) ? brandColor : "#6366f1" }}
502	                        />
503	                      </div>
504	                      <Input
505	                        placeholder="#6366f1"
506	                        value={brandColor}
507	                        onChange={(e) => setBrandColor(e.target.value)}
508	                        disabled={isSaving}
509	                        className="font-mono text-sm w-32"
510	                        maxLength={7}
511	                        aria-label="Brand color hex code"
512	                      />
513	                      {!isValidHex(brandColor) && brandColor.length > 0 && (
514	                        <span className="text-xs text-destructive">Invalid hex</span>
515	                      )}
516	                    </div>
517	                  </div>
518	
519	                  {/* Tagline */}
520	                  <div className="space-y-1.5">
521	                    <Label htmlFor="tagline" className="text-xs font-medium">
522	                      Tagline
523	                    </Label>
524	                    <Input
525	                      id="tagline"
526	                      placeholder="We're building the future of work"
527	                      value={tagline}
528	                      onChange={(e) => setTagline(e.target.value)}
529	                      disabled={isSaving}
530	                      maxLength={160}
531	                    />
532	                  </div>
533	
534	                  {/* About */}
535	                  <div className="space-y-1.5">
536	                    <Label htmlFor="about" className="text-xs font-medium">
537	                      About
538	                    </Label>
539	                    <Textarea
540	                      id="about"
541	                      placeholder="Tell candidates about your company, culture, and mission…"
542	                      value={about}
543	                      onChange={(e) => setAbout(e.target.value)}
544	                      disabled={isSaving}
545	                      rows={4}
546	                      className="resize-none text-sm"
547	                      maxLength={2000}
548	                    />
549	                  </div>
550	
551	                  {/* Active toggle */}
552	                  <div className="flex items-center justify-between rounded-lg border border-border p-3">
553	                    <div className="space-y-0.5">
554	                      <Label htmlFor="is-active" className="text-sm font-medium cursor-pointer">
555	                        Publish career page
556	                      </Label>
557	                      <p className="text-xs text-muted-foreground">
558	                        Make your career page publicly accessible to candidates.
559	                      </p>
560	                    </div>
561	                    <Switch
562	                      id="is-active"
563	                      checked={isActive}
564	                      onCheckedChange={setIsActive}
565	                      disabled={isSaving}
566	                      aria-label="Publish career page"
567	                    />
568	                  </div>
569	
570	                  {/* Preview link (when active + slug set) */}
571	                  {isActive && careerPageUrl && (
572	                    <div className="flex items-center gap-2 rounded-md bg-muted/50 px-3 py-2">
573	                      <Globe className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
574	                      <a
575	                        href={careerPageUrl}
576	                        target="_blank"
577	                        rel="noopener noreferrer"
578	                        className="flex-1 text-xs text-primary truncate hover:underline"
579	                      >
580	                        {careerPageUrl}
581	                      </a>
582	                      <button
583	                        onClick={copyUrl}
584	                        className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
585	                        aria-label="Copy career page URL"
586	                        type="button"
587	                      >
588	                        <Copy className="h-3.5 w-3.5" />
589	                      </button>
590	                      <a
591	                        href={careerPageUrl}
592	                        target="_blank"
593	                        rel="noopener noreferrer"
594	                        className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
595	                        aria-label="Open in new tab"
596	                      >
597	                        <ExternalLink className="h-3.5 w-3.5" />
598	                      </a>
599	                    </div>
600	                  )}
601	
602	                  {/* Save button */}
603	                  <div className="flex justify-end pt-1">
604	                    <Button
605	                      onClick={handleSave}
606	                      disabled={isSaving || slugStatus === "taken"}
607	                      className="gap-1.5"
608	                    >
609	                      {isSaving ? (
610	                        <Loader2 className="h-4 w-4 animate-spin" />
611	                      ) : (
612	                        <Save className="h-4 w-4" />
613	                      )}
614	                      Save changes
615	                    </Button>
616	                  </div>
617	                </div>
618	              )}
619	            </CardContent>
620	          </Card>
621	
622	          {/* ---------------------------------------------------------------- */}
623	          {/* Card 2: Published Jobs                                            */}
624	          {/* ---------------------------------------------------------------- */}
625	          <Card>
626	            <CardHeader className="pb-3">
627	              <CardTitle className="text-sm font-semibold flex items-center gap-2">
628	                <Globe className="h-4 w-4 text-primary" />
629	                Published Jobs
630	              </CardTitle>
631	              <CardDescription className="text-xs">
632	                Toggle which jobs appear on your career page.
633	              </CardDescription>
634	            </CardHeader>
635	            <CardContent className="p-0">
636	              {jobsLoading ? (
637	                <JobsSkeleton />
638	              ) : jobs.length === 0 ? (
639	                <div className="flex flex-col items-center justify-center py-14 space-y-3 text-center px-4">
640	                  <div className="rounded-xl bg-muted/50 p-4">
641	                    <Globe className="h-7 w-7 text-muted-foreground/40" />
