5	type TeamRole = "owner" | "admin" | "member";
6	
7	export interface TeamMember {
8	  id: string;
9	  user_id: string;
10	  role: TeamRole;
11	  joined_at: string;
12	  email?: string;
13	}
14	
15	export interface TeamInvitation {
16	  id: string;
17	  email: string;
18	  role: TeamRole;
19	  status: string;
20	  created_at: string;
21	  expires_at: string;
22	}
